const pool = require('../../config/db');
const withTransaction = require('../core/withTransaction');
const { AppError, NotFoundError, BadRequestError, ForbiddenError } = require('../core/errors');
const { TargetType, ActionType } = require('../utils/typeDefinitions');

class SectionService {
  async getSectionByBinderId(binderId, userId) {
    const member = await BinderDAO.getMember(pool, binderId, userId);
    if (!member || member.deleted_at) throw new ForbiddenError('바인더 멤버만 섹션을 조회할 수 있습니다');
    return await SectionDAO.findByBinderId(pool, binderId, userId);
  }

  async createSection(data, context) {
    const section = await withTransaction(async (client) => {
      const actor = await BinderDAO.getMember(client, data.binder_id, context.sender_id);
      if (!actor || actor.deleted_at || actor.role > 1) throw new ForbiddenError('manager 이상 권한이 필요합니다');
      const scope = data.access_scope ?? 0;
      if (![0, 1].includes(scope)) throw new BadRequestError('access_scope는 0 또는 1이어야 합니다');
      if (scope === 1 && !data.group_id) throw new AppError('private 섹션에는 그룹이 필요합니다', 422, 'SECTION_GRANT_REQUIRED');
      const created = await SectionDAO.create(client, {
        id: data.id || generateUUID(),
        binder_id: data.binder_id,
        title: data.title,
        access_scope: scope,
        group_id: scope === 1 ? data.group_id : null,
      });
      if (!created) throw new BadRequestError('그룹이 바인더에 속하지 않습니다');
      return created;
    });

    eventBus.emit('sync', {
      binder_id: data.binder_id,
      sender_id: context.sender_id,
      device_uuid: context.device_uuid,
      action: ActionType.CREATE, target_type: TargetType.SECTION, target_id: section.id,
    });

    return section;
  }

  async updateSection(sectionId, updateData, context) {
    const { section, result } = await withTransaction(async (client) => {
      const section = await SectionDAO.findById(client, sectionId, true);
      if (!section) throw new NotFoundError('섹션을 찾을 수 없습니다');
      const actor = await BinderDAO.getMember(client, section.binder_id, context.sender_id);
      if (!actor || actor.deleted_at || actor.role > 1) throw new ForbiddenError('manager 이상 권한이 필요합니다');
      const scope = updateData.access_scope ?? section.access_scope;
      if (![0, 1].includes(scope)) throw new BadRequestError('access_scope는 0 또는 1이어야 합니다');
      const hasGroupId = Object.prototype.hasOwnProperty.call(updateData, 'group_id');
      if (section.access_scope === 0 && scope === 1 && !hasGroupId) {
        throw new AppError('private 섹션에는 그룹이 필요합니다', 422, 'SECTION_GRANT_REQUIRED');
      }
      const groupId = scope === 0 ? null : (hasGroupId ? updateData.group_id : section.group_id);
      if (section.is_default && (scope === 1 || groupId !== null)) throw new BadRequestError('기본 섹션에는 그룹을 설정할 수 없습니다');
      if (scope === 1 && groupId === null) throw new AppError('private 섹션의 group_id는 비울 수 없습니다', 422, 'SECTION_GRANT_REQUIRED');

      const normalizedUpdate = { ...updateData, access_scope: scope, group_id: groupId };
      const result = await SectionDAO.update(client, sectionId, normalizedUpdate, true);
      if (!result) throw new BadRequestError('그룹이 바인더에 속하지 않습니다');
      return { section, result };
    });

    eventBus.emit('sync', {
      binder_id: section.binder_id,
      sender_id: context.sender_id,
      device_uuid: context.device_uuid,
      action: ActionType.UPDATE, target_type: TargetType.SECTION, target_id: sectionId,
    });

    return result;
  }

  async deleteSection(sectionId, context) {
    const { binder_id } = await withTransaction(async (client) => {
      const section = await SectionDAO.findById(client, sectionId);
      if (!section) throw new NotFoundError('섹션을 찾을 수 없습니다');
      if (section.is_default) throw new BadRequestError('기본 섹션은 삭제할 수 없습니다');
      const actor = await BinderDAO.getMember(client, section.binder_id, context.sender_id);
      if (!actor || actor.deleted_at || actor.role > 1) throw new ForbiddenError('manager 이상 권한이 필요합니다');

      await SectionDAO.softDelete(client, sectionId);
      return { binder_id: section.binder_id };
    });

    eventBus.emit('sync', {
      binder_id,
      sender_id: context.sender_id,
      device_uuid: context.device_uuid,
      action: ActionType.DELETE, target_type: TargetType.SECTION, target_id: sectionId,
    });
  }

  async listFiles(sectionId, query, userId) {
    const section = await SectionDAO.findById(pool, sectionId);
    if (!section) throw new NotFoundError('섹션을 찾을 수 없습니다');

    await this.assertContentAccess(sectionId, userId);

    return await AttachmentDAO.findBySection(pool, sectionId, query);
  }

  async assertContentAccess(sectionId, userId) {
    if (!(await SectionDAO.hasAccess(pool, sectionId, userId))) throw new ForbiddenError('섹션 콘텐츠 접근 권한이 없습니다', 'SECTION_ACCESS_DENIED');
  }

  async assertMessageAccess(messageId, userId) {
    const sectionId = await SectionDAO.findSectionIdByMessage(pool, messageId);
    if (!sectionId) throw new NotFoundError('메시지를 찾을 수 없습니다');
    return this.assertContentAccess(sectionId, userId);
  }

}

module.exports = { SectionService: new SectionService() };
const { SectionService } = require('../../services/sectionService');
const { MessageService } = require('../../services/messageService');
const { MessageDAO } = require('../../daos/messageDAO');
const pool = require('../../../config/db');
const asyncHandler = require('../../core/asyncHandler');

const sectionController = {
  // ============================================
  // Section CRUD
  // ============================================

  getSection: asyncHandler(async (req, res) => {
    const { binderId } = req.params;
    const section = await SectionService.getSectionByBinderId(binderId, req.user_id);
    res.json({ success: true, data: section });
  }),

  createSection: asyncHandler(async (req, res) => {
    const section = await SectionService.createSection(req.body, { sender_id: req.user_id, device_uuid: req.device_uuid });
    res.status(201).json({ success: true, data: section, message: '섹션이 생성되었습니다' });
  }),

  updateSection: asyncHandler(async (req, res) => {
    const { sectionId } = req.params;
    const section = await SectionService.updateSection(sectionId, req.body, { sender_id: req.user_id, device_uuid: req.device_uuid });
    res.json({ success: true, data: section, message: '섹션이 수정되었습니다' });
  }),

  deleteSection: asyncHandler(async (req, res) => {
    const { sectionId } = req.params;
    await SectionService.deleteSection(sectionId, { sender_id: req.user_id, device_uuid: req.device_uuid });
    res.json({ success: true, message: '섹션이 삭제되었습니다' });
  }),

  // ============================================
  // Messages
  // ============================================

  getMessages: asyncHandler(async (req, res) => {
    const { sectionId } = req.params;
    const { cursor_at, cursor_id, before_cursor, limit } = req.query;
    const parsedLimit = limit ? parseInt(limit, 10) : undefined;

    let cursorAt = cursor_at;
    let cursorId = cursor_id;

    if (before_cursor && !cursor_at) {
      const cursorMsg = await MessageDAO.findById(pool, before_cursor);
      if (cursorMsg) {
        cursorAt = cursorMsg.created_at;
        cursorId = cursorMsg.id;
      }
    }

    await SectionService.assertContentAccess(sectionId, req.user_id);
    const messages = await MessageService.getMessages(sectionId, {
      cursor_at: cursorAt, cursor_id: cursorId, limit: parsedLimit,
    });
    res.json({ success: true, data: messages });
  }),

  createMessage: asyncHandler(async (req, res) => {
    const { sectionId } = req.params;
    await SectionService.assertContentAccess(sectionId, req.user_id);
    const message = await MessageService.createMessage(sectionId, req.body, { sender_id: req.user_id, device_uuid: req.device_uuid });
    res.status(201).json({ success: true, data: message, message: '메시지가 생성되었습니다' });
  }),

  updateMessage: asyncHandler(async (req, res) => {
    const { messageId } = req.params;
    await SectionService.assertMessageAccess(messageId, req.user_id);
    const message = await MessageService.updateMessage(messageId, req.body, { sender_id: req.user_id, device_uuid: req.device_uuid });
    res.json({ success: true, data: message, message: '메시지가 수정되었습니다' });
  }),

  deleteMessage: asyncHandler(async (req, res) => {
    const { messageId } = req.params;
    await SectionService.assertMessageAccess(messageId, req.user_id);
    await MessageService.deleteMessage(messageId, { sender_id: req.user_id, device_uuid: req.device_uuid });
    res.json({ success: true, message: '메시지가 삭제되었습니다' });
  }),

  togglePin: asyncHandler(async (req, res) => {
    const { messageId } = req.params;
    await SectionService.assertMessageAccess(messageId, req.user_id);
    const result = await MessageService.togglePin(messageId, { sender_id: req.user_id, device_uuid: req.device_uuid });
    res.json({ success: true, data: result, message: '핀 상태가 변경되었습니다' });
  }),

  // ============================================
  // Files
  // ============================================

  listFiles: asyncHandler(async (req, res) => {
    const { sectionId } = req.params;
    const files = await SectionService.listFiles(sectionId, req.query, req.user_id);
    res.json({ success: true, data: files });
  }),

  // ============================================
  // Reactions
  // ============================================

  addReaction: asyncHandler(async (req, res) => {
    const { messageId } = req.params;
    const { emoji } = req.body;
    await SectionService.assertMessageAccess(messageId, req.user_id);
    const result = await MessageService.addReaction(messageId, emoji, { sender_id: req.user_id });
    res.status(201).json({ success: true, data: result });
  }),

  removeReaction: asyncHandler(async (req, res) => {
    const { messageId, emoji } = req.params;
    await SectionService.assertMessageAccess(messageId, req.user_id);
    await MessageService.removeReaction(messageId, emoji, { sender_id: req.user_id });
    res.json({ success: true, message: '리액션이 제거되었습니다' });
  }),

  // ============================================
  // Cursor (읽음 위치)
  // ============================================

  updateCursor: asyncHandler(async (req, res) => {
    const { sectionId } = req.params;
    await SectionService.assertContentAccess(sectionId, req.user_id);
    await MessageService.updateCursor(sectionId, req.user_id, req.body);
    res.json({ success: true });
  }),

  // ============================================
  // Pinned Messages
  // ============================================

  getPinnedMessages: asyncHandler(async (req, res) => {
    const { sectionId } = req.params;
    await SectionService.assertContentAccess(sectionId, req.user_id);
    const messages = await MessageService.getPinnedMessages(sectionId);
    res.json({ success: true, data: messages });
  }),

  // ============================================
  // Polls
  // ============================================

  getPoll: asyncHandler(async (req, res) => {
    const { messageId, pollId } = req.params;
    await SectionService.assertMessageAccess(messageId, req.user_id);
    const poll = await MessageService.getPoll(messageId, pollId, req.user_id);
    res.json({ success: true, data: poll });
  }),

  votePoll: asyncHandler(async (req, res) => {
    const { messageId, pollId } = req.params;
    await SectionService.assertMessageAccess(messageId, req.user_id);
    await MessageService.votePoll(messageId, pollId, req.body, req.user_id);
    res.json({ success: true });
  }),

  closePoll: asyncHandler(async (req, res) => {
    const { messageId, pollId } = req.params;
    await SectionService.assertMessageAccess(messageId, req.user_id);
    await MessageService.closePoll(messageId, pollId, { sender_id: req.user_id });
    res.json({ success: true });
  }),
};

module.exports = sectionController;
const express = require("express");
const router = express.Router();
const sectionController = require("../api/sections/sectionController");

router.route("/:sectionId")
  .patch(sectionController.updateSection)
  .delete(sectionController.deleteSection);

// Cursor (읽음 위치 갱신)
router.put("/:sectionId/cursor", sectionController.updateCursor);

// Pinned Messages — /:sectionId/messages/:messageId 보다 앞에 등록
router.get("/:sectionId/messages/pinned", sectionController.getPinnedMessages);

// Messages
router.route("/:sectionId/messages")
  .get(sectionController.getMessages)
  .post(sectionController.createMessage);

router.route("/:sectionId/messages/:messageId")
  .patch(sectionController.updateMessage)
  .delete(sectionController.deleteMessage);

router.patch("/:sectionId/messages/:messageId/pin", sectionController.togglePin);

// Files
router.get("/:sectionId/files", sectionController.listFiles);

// Reactions
router.post("/:sectionId/messages/:messageId/reactions", sectionController.addReaction);
router.delete("/:sectionId/messages/:messageId/reactions/:emoji", sectionController.removeReaction);

// Polls
router.get("/:sectionId/messages/:messageId/polls/:pollId", sectionController.getPoll);
router.post("/:sectionId/messages/:messageId/polls/:pollId/vote", sectionController.votePoll);
router.patch("/:sectionId/messages/:messageId/polls/:pollId/close", sectionController.closePoll);

module.exports = router;
class GroupDAO {
  async findById(conn, groupId, lock = false) {
    const { rows } = await conn.query(
      `SELECT id, binder_id, name, color, created_by, created_at, updated_at, deleted_at
       FROM groups WHERE id = $1 AND deleted_at IS NULL ${lock ? 'FOR UPDATE' : ''}`,
      [groupId]
    );
    return rows[0] || null;
  }

  async createGroup(conn, { id, binderId, name, color, createdBy }) {
    const { rows } = await conn.query(
      `INSERT INTO groups (id, binder_id, name, color, created_by)
       VALUES ($1, $2, $3, $4, $5)
       RETURNING id, binder_id, name, color, created_by, created_at, updated_at`,
      [id, binderId, name, color ?? null, createdBy]
    );
    return rows[0];
  }

  async getGroups(conn, binderId) {
    const { rows } = await conn.query(
      `SELECT g.id, g.binder_id, g.name, g.color, g.created_by, g.created_at, g.updated_at,
              COUNT(DISTINCT gm.user_id)::int AS member_count,
              COUNT(DISTINCT s.id)::int AS linked_section_count
       FROM groups g
       LEFT JOIN group_members gm ON gm.group_id = g.id AND gm.deleted_at IS NULL
       LEFT JOIN sections s ON s.group_id = g.id AND s.deleted_at IS NULL
       WHERE g.binder_id = $1 AND g.deleted_at IS NULL
       GROUP BY g.id ORDER BY g.created_at`,
      [binderId]
    );
    return rows;
  }

  async updateGroup(conn, groupId, { name, color }) {
    const { rows } = await conn.query(
      `UPDATE groups SET name = COALESCE($1, name), color = CASE WHEN $2::boolean THEN $3 ELSE color END,
       updated_at = now() WHERE id = $4 AND deleted_at IS NULL RETURNING *`,
      [name, Object.prototype.hasOwnProperty.call(arguments[2], 'color'), color, groupId]
    );
    return rows[0] || null;
  }

  async deleteGroup(conn, groupId) {
    await conn.query(
      `UPDATE binder_members SET primary_group_id = NULL, updated_at = now() WHERE primary_group_id = $1`, [groupId]
    );
    await conn.query(
      `UPDATE group_members SET deleted_at = now(), updated_at = now()
       WHERE group_id = $1 AND deleted_at IS NULL`, [groupId]
    );
    await conn.query(
      `UPDATE sections SET group_id = NULL, updated_at = now()
       WHERE group_id = $1 AND deleted_at IS NULL`, [groupId]
    );
    const { rowCount } = await conn.query(
      `UPDATE groups SET deleted_at = now(), updated_at = now() WHERE id = $1 AND deleted_at IS NULL`, [groupId]
    );
    return rowCount > 0;
  }

  async addMember(conn, { id, groupId, userId }) {
    const { rows } = await conn.query(
      `INSERT INTO group_members (id, group_id, user_id) VALUES ($1, $2, $3)
       RETURNING id, group_id, user_id, created_at, updated_at`, [id, groupId, userId]
    );
    return rows[0];
  }

  async removeMember(conn, groupId, userId) {
    const { rowCount } = await conn.query(
      `UPDATE group_members SET deleted_at = now(), updated_at = now()
       WHERE group_id = $1 AND user_id = $2 AND deleted_at IS NULL`, [groupId, userId]
    );
    await conn.query(
      `UPDATE binder_members bm SET primary_group_id = NULL, updated_at = now()
       FROM groups g WHERE g.id = $1 AND bm.binder_id = g.binder_id
         AND bm.user_id = $2 AND bm.primary_group_id = $1`, [groupId, userId]
    );
    return rowCount > 0;
  }

  async getMembers(conn, groupId) {
    const { rows } = await conn.query(
      `SELECT gm.id, gm.group_id, gm.user_id, gm.created_at, gm.updated_at
       FROM group_members gm WHERE gm.group_id = $1 AND gm.deleted_at IS NULL ORDER BY gm.created_at`, [groupId]
    );
    return rows;
  }
}

